function openJournal(chunks) {
  const decoder = new TextDecoder("utf-8");

  let iterator;
  let state = "new";
  let buffer = "";
  let lineNumber = 1;
  let returnPromise = null;
  let closePromise = null;

  function doneResult() {
    return { done: true, value: undefined };
  }

  function invokeReturn() {
    if (returnPromise) return returnPromise;

    if (!iterator) {
      returnPromise = Promise.resolve();
      return returnPromise;
    }

    returnPromise = Promise.resolve().then(() => {
      const method = iterator.return;
      if (typeof method === "function") {
        return method.call(iterator);
      }
      return undefined;
    });

    return returnPromise;
  }

  async function failRead(error) {
    state = "failed";
    const cleanup = invokeReturn();

    try {
      await cleanup;
    } catch (_) {
      // Preserve the original read error.
    }

    throw error;
  }

  function parseLine(text) {
    const line = lineNumber++;

    if (/^\s*$/.test(text)) {
      return null;
    }

    try {
      return {
        line,
        ok: true,
        value: JSON.parse(text)
      };
    } catch (_) {
      return {
        line,
        ok: false,
        text
      };
    }
  }

  async function next() {
    if (state === "closed" || state === "failed") {
      return doneResult();
    }

    if (state === "new") {
      try {
        const method = chunks[Symbol.asyncIterator];

        if (typeof method !== "function") {
          throw new TypeError("chunks must be an async iterable");
        }

        iterator = method.call(chunks);
        state = "open";
      } catch (error) {
        state = "failed";
        throw error;
      }
    }

    for (;;) {
      if (state === "closed" || state === "failed") {
        return doneResult();
      }

      const newline = buffer.indexOf("\n");

      if (newline !== -1) {
        let text = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);

        if (text.endsWith("\r")) {
          text = text.slice(0, -1);
        }

        const event = parseLine(text);
        if (event !== null) {
          return { done: false, value: event };
        }

        continue;
      }

      if (state === "eof") {
        if (buffer.length === 0) {
          return doneResult();
        }

        const text = buffer;
        buffer = "";

        const event = parseLine(text);
        if (event !== null) {
          return { done: false, value: event };
        }

        continue;
      }

      let result;

      try {
        result = await iterator.next();
      } catch (error) {
        return failRead(error);
      }

      if (state === "closed") {
        return doneResult();
      }

      if (result.done) {
        state = "eof";

        try {
          buffer += decoder.decode();
        } catch (error) {
          return failRead(error);
        }

        continue;
      }

      try {
        buffer += decoder.decode(result.value, { stream: true });
      } catch (error) {
        return failRead(error);
      }
    }
  }

  function close() {
    if (closePromise) {
      return closePromise;
    }

    if (state === "new" || state === "eof" || state === "failed") {
      state = "closed";
      closePromise = state === "closed" && returnPromise
        ? returnPromise
        : Promise.resolve();
      return closePromise;
    }

    state = "closed";
    closePromise = invokeReturn();
    return closePromise;
  }

  return { next, close };
}
